  const status = item.json['Video Status'] || item.json.Status || '';
  return !status || status.trim() === '';
});

if (!nextRow) {
  throw new Error('No pending topics found in the queue! All topics have been processed.');
}

// Pass all fields forward cleanly
return [{
  json: {
    Topic: nextRow.json.Topic || '',
    Hook: nextRow.json.Hook || nextRow.json['Hook Idea'] || '',
    Category: nextRow.json.Category || 'Tech',
    row_number: nextRow.json.row_number || 0
  }
}];

