// Parse Ollama response - robust handling for JSON and plain text
const item = $input.first();
if (!item || !item.json) {
  throw new Error('No item from Ollama node');
}

let raw = (item.json.response || '').trim();
if (!raw) {
  throw new Error('Ollama returned empty response field');
}

// Strip markdown fences if present
raw = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();

// Try to parse as JSON
let parsed = null;
try {
  parsed = JSON.parse(raw);
} catch (e1) {
  // Try extracting the first complete JSON object
  const match = raw.match(/\{[\s\S]+\}/);
  if (match) {
    try { parsed = JSON.parse(match[0]); } catch (e2) { parsed = null; }
  }
}

// If still no parsed JSON, build a simple debate from the plain text
if (!parsed || !Array.isArray(parsed.script) || parsed.script.length === 0) {
  // Ollama returned plain text - split into sentences and alternate speakers
  const sentences = raw
    .replace(/["]/g, '')
    .split(/[.!?]+/)
    .map(s => s.trim())
    .filter(s => s.length > 10)
    .slice(0, 10);

  if (sentences.length === 0) {
    throw new Error('Could not extract any usable content from AI response: ' + raw.substring(0, 300));
  }

  const topic = item.json.prompt_topic || 'this topic';
  parsed = {
    title: 'The TRUTH About ' + topic.substring(0, 40),
    description: topic + ' debate #shorts #facts #debate',
    on_screen_title: 'TRUTH REVEALED',
    topic: topic,
    row_number: 0,
    script: sentences.map((text, i) => ({
      speaker: i % 2 === 0 ? 'character_a' : 'character_b',
      text: text,
      visual_proof_prompt: i % 3 === 0 ? 'cinematic dramatic shot illustrating: ' + text.substring(0, 80) : null
    }))
  };
}

// Validate and normalize the script array
const scriptArray = (parsed.script || []).map((turn, i) => ({
  speaker: turn.speaker || (i % 2 === 0 ? 'character_a' : 'character_b'),
  text: (turn.text || turn.dialogue || '').trim(),
  visual_proof_prompt: turn.visual_proof_prompt || null
})).filter(t => t.text.length > 0);

if (scriptArray.length === 0) {
  throw new Error('Script has no valid lines after parsing');
}

return [{
  json: {
    script: scriptArray,
    title: (parsed.title || 'Mind-Blowing Debate').substring(0, 100),
    description: parsed.description || '#shorts #debate #facts',
    on_screen_title: (parsed.on_screen_title || 'TOP REVEAL').toUpperCase().substring(0, 50),
    topic: parsed.topic || '',
    row_number: typeof parsed.row_number === 'number' ? parsed.row_number : 0
  }
}];

// Validate video was created and pass all metadata downstream
const item = $input.first();
if (!item || !item.json) {
  throw new Error('No response from Local Video Maker');
}

const status = item.json.status || '';
const videoPath = item.json.video_path || '';

if (status === 'error') {
  throw new Error('Video generation failed: ' + (item.json.error || 'unknown error'));
}

if (!videoPath) {
  throw new Error('No video_path in response: ' + JSON.stringify(item.json).substring(0, 300));
}

return [{
  json: {
    status: 'success',
    video_path: videoPath,
    task_id: item.json.task_id || '',
    title: item.json.title || '',
    description: item.json.description || '#shorts',
    topic: item.json.topic || '',
    row_number: item.json.row_number || 0,
    duration: item.json.duration || 0
  }
}];
